(function(){
  const techs={ftir:['FTIR','cm-1'],h1:['H-NMR','ppm'],c13:['C-NMR','ppm'],uv:['UV–VIS','nm'],xrd:['XRD','2theta-deg'],fluorescence:['Fluorescence','nm'],raman:['Raman','cm-1'],ms:['MS','m/z']};
  const formula=v=>String(v||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])).replace(/([A-Za-z\]\)])(\d+)/g,'$1<sub>$2</sub>').replace(/([+-])$/,'<sup>$1</sup>');
  const file64=file=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=()=>reject(Error('File could not be read'));r.readAsDataURL(file)});
  function checks(name,legend,values,required=true){return '<fieldset class="condition-set"><legend>'+legend+'</legend><div class="tick-options">'+values.map(([v,l])=>'<label><input type="checkbox" name="'+name+'" value="'+v+'" data-one="'+name+'">'+l+'</label>').join('')+'</div>'+(required?'':'')+'</fieldset>'}
  function bindExclusive(root){root.querySelectorAll('[data-one]').forEach(input=>input.onchange=()=>{if(input.checked)root.querySelectorAll('[data-one="'+input.dataset.one+'"]').forEach(other=>{if(other!==input)other.checked=false})})}
  function upload({app,api,esc}){
    const requestId=crypto.randomUUID(),files=new Map();
    app.innerHTML='<a class="focus-back" href="#home" aria-label="Back to search">‹</a><section class="student-upload"><h1>Explore your sample</h1><form id="student-upload"><label class="drop-file"><span>FTIR</span><strong>Choose an instrument file</strong><small>CSV / TXT · your original values stay unchanged</small><input type="file" name="ftir-file" accept=".csv,.txt,.tsv" required></label><div id="trace-choice"></div><div class="upload-conditions">'+checks('phase','Physical state',[['solid','Solid / powder'],['liquid','Neat liquid'],['solution','Solution'],['gas','Gas'],['unknown','Not known']])+checks('measurement','FTIR acquisition',[['ATR','ATR'],['KBr transmission','KBr pellet'],['liquid transmission','Liquid transmission'],['gas transmission','Gas transmission'],['reflectance','Reflectance / DRIFT'],['unknown','Not known']])+checks('solvent','Solvent',[['none','None'],['water','Water'],['ethanol','Ethanol'],['methanol','Methanol'],['acetone','Acetone'],['DMSO','DMSO'],['other','Other'],['unknown','Not known']])+checks('yMode','Vertical axis',[['transmittance-percent','Transmittance (%)'],['absorbance','Absorbance'],['intensity','Other / unknown']])+checks('sampleType','Sample',[['single','Expected single compound'],['mixture','Mixture / formulation'],['unknown','Not known']])+'</div><details class="acquisition-extra"><summary>More conditions</summary><div class="fields"><label>Other solvent<input name="solvent-other" placeholder="Solvent or solvent mixture"></label><label>Sample label<input name="label" placeholder="Defaults to filename"></label><label>Resolution (cm⁻¹)<input name="resolution" type="number" min="0" step="any"></label><label>Number of scans<input name="scans" type="number" min="1"></label><label>Temperature (°C)<input name="temperature" type="number" step="any"></label><label>Instrument<input name="instrument"></label></div>'+checks('processing','Processing',[['raw','Raw / uncorrected'],['baseline-corrected','Baseline corrected'],['normalized','Normalized'],['unknown','Not known']],false)+checks('background','Background',[['fresh','Fresh background collected'],['not-fresh','Not fresh / no background'],['unknown','Not known']],false)+'<label>Preparation / relevant notes<textarea name="notes" placeholder="Drying, KBr ratio, ATR crystal, water/CO₂ correction, contaminants, purity, pH or concentration"></textarea></label></details><details class="acquisition-extra"><summary>Add NMR, UV–Vis, MS or another technique</summary><div class="extra-files">'+Object.entries(techs).filter(([t])=>t!=='ftir').map(([t,[label,unit]])=>'<section data-extra="'+t+'"><h3>'+label+'</h3><label>CSV / TXT<input type="file" name="'+t+'-file" accept=".csv,.txt,.tsv"></label><div id="trace-'+t+'"></div><label>Solvent<input name="'+t+'-solvent" placeholder="none, water, CDCl₃…"></label>'+(['h1','c13'].includes(t)?'<label>Observed nucleus frequency (MHz)<input type="number" name="'+t+'-frequency" min="1" step="any" placeholder="'+(t==='h1'?'e.g. 400':'e.g. 100.6, not the proton frequency')+'"></label><label>Data format<div class="tick-options"><label><input type="checkbox" data-one="'+t+'-format" name="'+t+'-format" value="continuous" checked>Continuous</label><label><input type="checkbox" data-one="'+t+'-format" name="'+t+'-format" value="peaks">Peak list</label></div></label>':'')+(t==='uv'?'<label>Vertical axis<div class="tick-options"><label><input type="checkbox" name="uv-yMode" value="absorbance" data-one="uv-yMode" checked>Absorbance</label><label><input type="checkbox" name="uv-yMode" value="intensity" data-one="uv-yMode">Relative intensity</label></div></label>':'')+(t==='xrd'?'<label>X-ray radiation<input name="xrd-radiation" placeholder="e.g. Cu Kα, wavelength 1.5406 Å"></label><label>Phase / polymorph<input name="xrd-polymorph" placeholder="Not known"></label>':'')+(t==='fluorescence'?'<label>Excitation wavelength (nm)<input type="number" name="fluorescence-excitation" min="100"></label>':'')+(t==='ms'?'<p class="small muted">Two columns: m/z, abundance (peak list).</p><label>Ionization<input name="ms-ionization" value="EI 70 eV" placeholder="EI 70 eV, ESI+, APCI…"></label>':'')+'</section>').join('')+'</div></details><div class="student-submit"><small>Local analysis. Candidates are hypotheses, not confirmed identities.</small><button class="primary" id="student-run">Analyse sample</button></div><p id="student-error" role="alert"></p></form></section>';
    const form=app.querySelector('form');bindExclusive(form);
    for(const t of Object.keys(techs))form.elements[t+'-file'].onchange=async e=>{
      const f=e.target.files[0],holder=app.querySelector(t==='ftir'?'#trace-choice':'#trace-'+t);files.delete(t);holder.innerHTML='';if(!f)return;
      try{if(f.size>25000000)throw Error('Maximum 25 MB per file');const base64=await file64(f),info=await api('/api/inspect-spectrum',{base64});if(!form.isConnected)return;files.set(t,{file:f,base64,info});holder.innerHTML='<fieldset class="condition-set"><legend>Choose one trace · '+info.rows.toLocaleString()+' points</legend><div class="tick-options trace-options">'+info.traces.map((z,i)=>'<label><input type="checkbox" data-one="'+t+'-column" name="'+t+'-column" value="'+z.column+'" '+(i===0?'checked':'')+'>'+esc(z.name)+(z.normalized?' · normalized':'')+'</label>').join('')+'</div></fieldset>';bindExclusive(holder);const infer=()=>{const n=Number(new FormData(form).get(t+'-column')),z=info.traces.find(x=>x.column===n);if(t==='ftir'&&z)form.querySelectorAll('[name=yMode]').forEach(x=>x.checked=x.value===z.yMode)};holder.addEventListener('change',infer);infer();}
      catch(e){holder.innerHTML='<p class="input-error">'+esc(e.message)+'</p>'}
    };
    form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('#student-run'),error=form.querySelector('#student-error');error.textContent='';button.disabled=true;
      try{const fd=new FormData(form),meta={xUnit:'cm-1',format:'continuous'};for(const k of ['phase','measurement','solvent','yMode','sampleType']){meta[k]=fd.get(k);if(!meta[k])throw Error('Tick one option for '+k+'. Not known is allowed.')}if(meta.solvent==='other'){meta.solvent=String(fd.get('solvent-other')||'').trim();if(!meta.solvent)throw Error('Enter the other solvent.')}for(const k of ['resolution','scans','temperature','instrument','notes','processing','background'])meta[k]=fd.get(k)||'';
        if(!files.has('ftir'))throw Error('Choose a parseable FTIR file and wait for the trace preview.');
        const payload=[];for(const [t,{file,base64,info}]of files){const column=Number(fd.get(t+'-column'));if(!column)throw Error('Choose one trace for '+techs[t][0]);const z=info.traces.find(r=>r.column===column),m=t==='ftir'?{...meta}:{xUnit:techs[t][1],format:t==='ms'?'peaks':fd.get(t+'-format')||'continuous',ionization:t==='ms'?fd.get('ms-ionization')||'unknown':'',yMode:t==='uv'?fd.get('uv-yMode')||'absorbance':'intensity',solvent:fd.get(t+'-solvent')||'unknown',phase:meta.phase,measurement:t};m.frequency=fd.get(t+'-frequency')||'';m.yColumn=String(column);m.normalized=String(z.normalized);m.radiation=fd.get(t+'-radiation')||'';m.polymorph=fd.get(t+'-polymorph')||'unknown';m.excitation=fd.get(t+'-excitation')||'';payload.push({name:file.name,technique:t,metadata:m,base64})}
        window.focusPortal.startUpload();window.focusPortal.updateUpload(20);const saved=await api('/api/samples',{id:requestId,kind:'unknown',label:fd.get('label')||files.get('ftir').file.name.replace(/\.[^.]+$/,''),metadata:{notes:meta.notes,provenance:'Student instrument upload',license:'Private research use only; not authorized for public redistribution'},files:payload});window.focusPortal.updateUpload(80);location.hash='unknown/'+saved.id;
      }catch(e){window.focusPortal.stopUpload();error.textContent=e.message;button.disabled=false}
    };
  }
  async function results({app,api,esc,structure,sample,matches,alive,openSpectrum,onReady}){
    let offset=0,query='';const d=await api('/api/samples/'+sample.id+'/analysis');if(!alive())return;await onReady?.();if(!alive())return;
    app.innerHTML='<a class="focus-back" href="#home" aria-label="Back to search">‹</a><section class="analysis-stage"><div class="analysis-heading"><div><p class="small muted">'+esc(sample.label)+'</p><h1>What does your FTIR suggest?</h1></div><button id="view-upload">View FTIR</button></div><div class="feature-chips">'+(d.analysis?.features||[]).map(f=>'<span title="'+esc(f.note)+'">'+esc(f.label)+'<small>'+f.peaks.map(x=>Math.round(x)).join(', ')+' cm⁻¹</small></span>').join('')+'</div><details class="analysis-details"><summary>Fingerprint, conditions & limitations</summary>'+(d.analysis?'<p class="small">Fingerprint region: '+d.analysis.fingerprint.range.map(Math.round).join('–')+' cm⁻¹ · '+d.analysis.fingerprint.peaks.length+' detected peaks. No exact fingerprint match is inferred from these rules.</p><p class="small muted">'+esc(d.analysis.fingerprint.peaks.map(x=>Math.round(x)).join(', '))+'</p><p class="small">'+esc(Object.entries(d.analysis.conditions).filter(([,v])=>v).map(([k,v])=>k+': '+v).join(' · '))+'</p>'+d.analysis.warnings.map(w=>'<p class="small muted">'+esc(w)+'</p>').join('')+d.analysis.sources.map(s=>'<p class="small"><a href="'+esc(s.url)+'" target="_blank" rel="noopener noreferrer">'+esc(s.title)+'</a></p>').join(''):'<p>'+esc(d.reason)+'</p>')+'</details><div class="measured-matches"><h2>Measured-reference matches</h2>'+(matches.results.length?matches.results.map(r=>'<button data-measured="'+r.compound.id+'">'+esc(r.compound.name)+' · similarity '+r.mean.toFixed(3)+' (not confidence)</button>').join(''):'<p class="small muted">No compatible reviewed reference. The suggestions below use structure rules only.</p>')+'</div><div class="candidate-heading"><h2>Structure suggestions</h2><span id="candidate-count" class="small muted">'+d.total+' within this catalog · not exhaustive</span></div><p class="small muted">Select a hypothesis after reviewing your bands. FTIR alone may not distinguish these compounds.</p><div id="student-candidates" class="student-candidates"></div><div class="pager"><button id="candidate-prev" disabled>Previous</button><span id="candidate-page"></span><button id="candidate-next">Next</button></div><div class="no-match-row"><button id="no-candidate">None of these / keep unknown</button><a href="#upload-unknown">New sample</a></div><p id="selection-error" role="alert"></p></section>';
    app.querySelector('#view-upload').onclick=()=>openSpectrum('ftir');
    const filter=document.createElement('form');filter.className='candidate-filter';filter.innerHTML='<input aria-label="Filter suggested structures" placeholder="Filter suggestions by name or formula"><button>Filter</button>';app.querySelector('#student-candidates').before(filter);filter.onsubmit=async e=>{e.preventDefault();query=filter.querySelector('input').value.trim();offset=0;try{await draw(await api('/api/samples/'+sample.id+'/analysis?q='+encodeURIComponent(query)))}catch(e){app.querySelector('#selection-error').textContent=e.message}};
    const select=async id=>{try{await api('/api/samples/'+sample.id+'/selection',{compoundId:id});if(alive())location.hash='candidate/'+sample.id+'/'+id}catch(e){app.querySelector('#selection-error').textContent=e.message}};
    app.querySelectorAll('[data-measured]').forEach(b=>b.onclick=()=>select(Number(b.dataset.measured)));
    app.querySelector('#no-candidate').onclick=async()=>{await api('/api/samples/'+sample.id+'/selection',{compoundId:null});app.querySelector('#selection-error').textContent='Identity remains unknown. Collect orthogonal evidence such as NMR or mass spectrometry.'};
    const draw=async data=>{if(!alive())return;const holder=app.querySelector('#student-candidates');app.querySelector('#candidate-count').textContent=data.total+' within this catalog · not exhaustive';holder.innerHTML=data.rows.map(r=>'<button class="structure-candidate" data-choice="'+r.compound.id+'"><span class="candidate-drawing" data-mol="'+r.compound.id+'"></span><strong>'+esc(r.compound.name)+'</strong><span class="molecular-formula">'+formula(r.compound.formula)+'</span><small>'+esc(r.supported.join(' · '))+'</small>'+(r.unexplained.length?'<small class="unexplained">Unexplained: '+esc(r.unexplained.join(' · '))+'</small>':'')+'</button>').join('')||'<p class="minimal-message">'+esc(data.reason||'No structural suggestions')+'</p>';holder.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>select(Number(b.dataset.choice)));app.querySelector('#candidate-prev').disabled=offset===0;app.querySelector('#candidate-next').disabled=offset+18>=data.total;app.querySelector('#candidate-page').textContent=data.total?(offset+1)+'–'+Math.min(offset+18,data.total)+' of '+data.total:'0';for(const r of data.rows){const target=holder.querySelector('[data-mol="'+r.compound.id+'"]');if(target)await structure(r.compound.smiles,target)}};
    const page=async change=>{offset=Math.max(0,offset+change);try{await draw(await api('/api/samples/'+sample.id+'/analysis?offset='+offset+'&q='+encodeURIComponent(query)))}catch(e){app.querySelector('#selection-error').textContent=e.message}};app.querySelector('#candidate-prev').onclick=()=>page(-18);app.querySelector('#candidate-next').onclick=()=>page(18);await draw(d);
  }
  window.studentWorkflow={upload,results,formula};
})();
